1277	      }
1278	      const other = parseLockInfo(otherText);
1279	      if (other === null) {
1280	        throw new BizError(
1281	          `恢复协调文件 ${recoveryPath} 内容无法辨认，无法确认另一恢复进程是否存活，拒绝继续（请人工核查后自行处理该文件）`,
1282	        );
1283	      }
1284	      if (other.host !== hostname()) {
1285	        throw new BizError(
1286	          `恢复协调文件由另一台主机（${other.host}）的进程 ${other.pid} 取得，本机无法确认其是否已退出，拒绝继续`,
1287	        );
1288	      }
1289	      let otherAlive = false;
