1296	        }
1297	      }
1298	      if (otherAlive) {
1299	        throw new BizError(
1300	          `另一恢复进程 ${other.pid} 正在处理本数据文件的写入保护，本次不重复解除；请等待其结束后重试`,
1301	        );
