1353	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
1354	  const problems: string[] = [];
1355	  const seen = new Set<string>();
1356	  const dupes: string[] = [];
1357	  for (const id of rawIds) {
1358	    if (seen.has(id)) {
1359	      if (!dupes.includes(id)) dupes.push(id);
1360	    }
1361	    seen.add(id);
1362	  }
1363	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
1364	
1365	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
1366	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
1367	
1368	  if (problems.length > 0) throw new BizError(problems.join('\n'));
1369	  return [...seen].sort();
1370	}
