190	  assertFileBytes(df, bytesAfter, '整体无解查询后');
191	});
192	
193	// ---------------------------------------------------------------------------
194	// 3. 最早时间优先于组合字典序；同一最早开始的多个组合取标识序列字典序最小
195	// ---------------------------------------------------------------------------
196	
197	test('取舍：更早开始优先于更小标识组合；同一最早开始取字典序最小序列', (t) => {
198	  const dir = tempDir(t);
199	  const df = join(dir, 'data.json');
200	  addResource(df, '晚开放场地', [['2026-10-12T10:00', '2026-10-12T20:00']]); // R0001，10:00 起开放
201	  addResource(df, '早开放场地甲', [['2026-10-12T08:00', '2026-10-12T20:00']]); // R0002，08:00 起开放
202	  addResource(df, '早开放场地乙', [['2026-10-12T08:00', '2026-10-12T20:00']]); // R0003，08:00 起开放
203	
204	  // (a) R0001 标识更小但 10:00 才可用；R0002 08:00 即可用：取更早的 08:00（R0002）
205	  const r1 = findSlot(df, '2026-10-12T08:00/2026-10-12T12:00', '60', ['R0001,R0002'], '更早开始优先');
206	  assertSlot(r1, '2026-10-12T08:00', '2026-10-12T09:00', ['R0002'], '更早开始优先');
