  assert.equal(b1.start, '2026-10-12T14:00', '既有预约 B0001 不被第二次提交改变');
  assert.equal(b2.status, 'cancelled', '既有预约 B0002 不被第二次提交复活');
  assert.equal(store.waitlist?.length ?? 0, 0, '不产生候补记录');
});

